-- ── Query 1 ────────────────────────────────────────────────────────────
SELECT     REPORT_DATE  AS \"Report Date\",     RECORD_CATEGORY AS \"Record Category\",     CASE RECORD_CATEGORY         WHEN 'UNMATCHED'         THEN 'UNMATCHED RECEIPT: Receipt exists in RMS; invoice not yet matched in ReIM'         WHEN 'CLOSED_WRITEOFF'         THEN 'WRITE-OFF SENT TO FINANCIALS: invclshp.pc closed this shipment; interfaced to AP'         ELSE 'REVIEW'     END                                                   AS \"Record Category DESC\",     DAYS_UNMATCHED AS \"Days Unmatched\",     CASE         WHEN RECORD_CATEGORY = 'CLOSED_WRITEOFF' AND RECEIPT_COST_RAW &gt; 0         THEN '1 - CRITICAL: Write-off with positive cost value sent to financials'         WHEN RECORD_CATEGORY = 'UNMATCHED' AND DAYS_UNMATCHED &gt; 30         THEN '2 - HIGH: Unmatched over 30 days - invprg.pc may purge invoice before ReIM matches'         WHEN RECORD_CATEGORY = 'UNMATCHED' AND DAYS_UNMATCHED &gt; 15         THEN '3 - MEDIUM: Unmatched 15-30 days - chase ReIM matching team'         WHEN RECORD_CATEGORY = 'CLOSED_WRITEOFF' AND RECEIPT_COST_RAW = 0         THEN '4 - REVIEW: Zero-value write-off closed by invclshp.pc'         ELSE '5 - MONITOR: Under 15 days unmatched'     END                                                   AS \"Urgency Level\",      CASE         WHEN DAYS_UNMATCHED &gt; 30 THEN 'OVERDUE - Over 30 Days'         WHEN DAYS_UNMATCHED &gt; 15 THEN 'REVIEW - 15 to 30 Days'         WHEN DAYS_UNMATCHED &gt; 7  THEN 'MONITOR - 7 to 15 Days'         ELSE 'RECENT - Under 7 Days'     END                                                   AS \"Aging Band\",     SHIPMENT_NO                                           AS \"Shipment No\",     MATCH_STATUS                                          AS \"Match Status\",     CASE MATCH_STATUS         WHEN 'U' THEN 'Unmatched'         WHEN 'M' THEN 'Matched'         WHEN 'C' THEN 'Closed - Write-off by invclshp.pc'         ELSE NVL(MATCH_STATUS, 'NOT SET')     END                                                   AS \"Match Status DESC\",     ASN_NUMBER                                            AS \"ASN Number\",     RECEIPT_DATE                                          AS \"Receipt Date\",     PO_NUMBER                                             AS \"PO Number\",     PO_STATUS                                             AS \"PO Status\",     CASE PO_STATUS         WHEN 'A' THEN 'Approved' WHEN 'C' THEN 'Closed'         WHEN 'W' THEN 'Worksheet' WHEN 'S' THEN 'Submitted'         ELSE PO_STATUS     END                                                   AS \"PO Status DESC\",     SUPPLIER_ID                                           AS \"Supplier ID\",     SUPPLIER_NAME                                         AS \"Supplier Name\",     SUPPLIER_STATUS                                       AS \"Supplier Status\",     ORIGIN_COUNTRY_ID                                     AS \"Origin Country ID\",     VPN,     LOCATION_ID                                           AS \"Location ID\",     LOC_TYPE                                              AS \"LOC Type\",     CASE LOC_TYPE         WHEN 'S' THEN STORE_NAME         WHEN 'W' THEN WH_NAME         ELSE TO_CHAR(LOCATION_ID)     END                                                   AS \"Location Name\",     DEPT_NO                                               AS \"Dept No\",     DEPT_NAME                                             AS \"Dept Name\",     CLASS_NO                                              AS \"Class No\",     CLASS_NAME                                            AS \"Class Name\",     SUBCLASS_NO                                           AS \"Subclass No\",     SUBCLASS_NAME                                         AS \"Subclass Name\",     ITEM_ID                                               AS \"Item ID\",     ITEM_DESCRIPTION                                      AS \"Item Description\",     UOM,     QTY_ORDERED                                           AS \"QTY Ordered\",     QTY_RECEIVED                                          AS \"QTY Received\",     UNIT_COST                                             AS \"Unit Cost\",     ROUND(RECEIPT_COST_RAW, 2)                            AS \"Receipt Cost\",     INVC_XREF_ID                                          AS \"Invc Xref ID\",     LINKED_INVOICE_ID                                     AS \"Linked Invoice ID\",     INVOICE_TYPE                                          AS \"Invoice Type\",     CASE INVOICE_TYPE         WHEN 'RTV'  THEN 'Return To Vendor Invoice'         WHEN 'CONS' THEN 'Consignment Invoice'         WHEN 'CS'   THEN 'Credit Note'         WHEN 'CN'   THEN 'Credit Note Request'         WHEN 'DM'   THEN 'Debit Memo'         WHEN 'OI'   THEN 'Ordinary Invoice'         ELSE NVL(INVOICE_TYPE, 'NO INVOICE CREATED')     END                                                   AS \"Invoice Type DESC\",     INVOICE_DATE                                          AS \"Invoice Date\",     INVOICE_AMOUNT                                        AS \"Invoice Amount\",     INVOICE_CURRENCY                                      AS \"Invoice Currency\",     PAYMENT_TERMS                                         AS \"Payment Terms\",     PAYMENT_DUE_DATE                                      AS \"Payment Due Date\",     VENDOR_DOC_NO                                         AS \"Vendor Doc No\",     INVOICE_MATCH_STATUS                                  AS \"Invoice Match Status\",     CASE INVOICE_MATCH_STATUS         WHEN 'U' THEN 'Unmatched in ReIM'         WHEN 'M' THEN 'Matched in ReIM'         WHEN 'A' THEN 'Auto-matched'         WHEN 'E' THEN 'Error in ReIM'         ELSE NVL(INVOICE_MATCH_STATUS, 'NO INVOICE IN RMS')     END                                                   AS \"Invoice Match Status DESC\",     EXTRACTED_TO_REIM                                     AS \"Extracted To Reim\",     CASE EXTRACTED_TO_REIM         WHEN 'Y' THEN 'YES - Extracted by edidlinv.pc to ReIM file'         WHEN 'N' THEN 'NO - Not yet extracted to ReIM'         ELSE 'NO INVOICE - invclshp.pc write-off, no invoice created'     END                                                   AS \"Reim Extraction Status\",     CASE         WHEN RECORD_CATEGORY = 'CLOSED_WRITEOFF' AND RECEIPT_COST_RAW &gt; 0         THEN 'WRITE-OFF SENT TO FINANCIALS: AP should have received debit from invclshp.pc closure'         WHEN RECORD_CATEGORY = 'CLOSED_WRITEOFF' AND RECEIPT_COST_RAW = 0         THEN 'ZERO-VALUE WRITE-OFF: Closed with no financial impact'         WHEN LINKED_INVOICE_ID IS NOT NULL AND EXTRACTED_TO_REIM = 'Y'         THEN 'INVOICE EXTRACTED TO REIM: Awaiting matching in ReIM system'         WHEN LINKED_INVOICE_ID IS NOT NULL AND NVL(EXTRACTED_TO_REIM,'N') = 'N'         THEN 'INVOICE NOT EXTRACTED: edidlinv.pc has not yet extracted to ReIM file'         WHEN LINKED_INVOICE_ID IS NULL         THEN 'NO INVOICE IN RMS: Receipt received but no invoice created - check supplier'         ELSE 'REVIEW'     END                                                   AS \"Financial Status\",     CASE         WHEN RECORD_CATEGORY = 'CLOSED_WRITEOFF'         THEN 'CLOSED BY invclshp.pc: Shipment exceeded Close Open Ship Days with no open invoice'         WHEN LINKED_INVOICE_ID IS NULL         THEN 'NO INVOICE CREATED: Supplier has not submitted invoice; check payment terms'         WHEN EXTRACTED_TO_REIM = 'N'         THEN 'EDIDLINV NOT RUN: Invoice exists but edidlinv.pc has not extracted it to ReIM'         WHEN DAYS_UNMATCHED &gt; 30         THEN 'REIM MATCHING DELAYED: Invoice extracted but ReIM has not matched it'         ELSE 'NORMAL: Recent receipt awaiting ReIM invoice matching cycle'     END                                                   AS \"Root Cause\",     CASE         WHEN RECORD_CATEGORY = 'CLOSED_WRITEOFF' AND RECEIPT_COST_RAW &gt; 0         THEN 'Confirm AP has received write-off posting; verify GL account via fifgldn1/fifgldn2'         WHEN LINKED_INVOICE_ID IS NULL AND DAYS_UNMATCHED &gt; 15         THEN 'Invoice missing: contact supplier to submit invoice; raise manual invoice in ReIM if needed'         WHEN EXTRACTED_TO_REIM = 'N'         THEN 'Run edidlinv.pc or check extraction schedule; invoice must reach ReIM before payment terms expire'         WHEN DAYS_UNMATCHED &gt; 30         THEN 'Chase ReIM matching team; check IM_MATCH_QUEUE in ReIM for blocking exceptions'         WHEN DAYS_UNMATCHED &gt; 15         THEN 'Follow up with ReIM team; ensure invoice is in IM_DOC_HEAD and not in error status'         ELSE 'Monitor - within normal ReIM matching window'     END                                                   AS \"Recommended Action\",     COMMENTS FROM (

