repColumnName\":\"Reim Extraction Status\",\"isUserCalculation\":false},{\"prepColumnName\":\"Financial Status\",\"isUserCalculation\":false},{\"prepColumnName\":\"Root Cause\",\"isUserCalculation\":false},{\"prepColumnName\":\"Recommended Action\",\"isUserCalculation\":false},{\"prepColumnName\":\"COMMENTS\",\"isUserCalculation\":false}],\"transforms\":[{\"id\":\"1\",\"type\":\"PROPERTY_CHANGE\",\"sourceColumns\":[\"Shipment No\"],\"expressionSourceColumns\":[\"Shipment No\"],\"outputColumns\":[],\"options\":{\"outputColumnAggrRule\":\"none\",\"outputColumnDisplayName\":\"Shipment No\",\"outputColumnRole\":\"Attribute\",\"afterColumn\":\"Shipment No\"},\"applied\":true,\"inplace\":true,\"rename\":false,\"allowEdit\":false,\"generatesOutputColumns\":false,\"unsavedTransform\":false,\"parentId\":null},{\"id\":\"2\",\"type\":\"PROPERTY_CHANGE\",\"sourceColumns\":[\"PO Number\"],\"expressionSourceColumns\":[\"PO Number\"],\"outputColumns\":[],\"options\":{\"outputColumnAggrRule\":\"none\",\"outputColumnDisplayName\":\"PO Number\",\"outputColumnRole\":\"Attribute\",\"afterColumn\":\"PO Number\"},\"applied\":true,\"inplace\":true,\"rename\":false,\"allowEdit\":false,\"generatesOutputColumns\":false,\"unsavedTransform\":false,\"parentId\":\"1\"},{\"id\":\"3\",\"type\":\"PROPERTY_CHANGE\",\"sourceColumns\":[\"Supplier ID\"],\"expressionSourceColumns\":[\"Supplier ID\"],\"outputColumns\":[],\"options\":{\"outputColumnAggrRule\":\"none\",\"outputColumnDisplayName\":\"Supplier ID\",\"outputColumnRole\":\"Attribute\",\"afterColumn\":\"Supplier ID\"},\"applied\":true,\"inplace\":true,\"rename\":false,\"allowEdit\":false,\"generatesOutputColumns\":false,\"unsavedTransform\":false,\"parentId\":\"2\"},{\"id\":\"4\",\"type\":\"PROPERTY_CHANGE\",\"sourceColumns\":[\"Location ID\"],\"expressionSourceColumns\":[\"Location ID\"],\"outputColumns\":[],\"options\":{\"outputColumnAggrRule\":\"none\",\"outputColumnDisplayName\":\"Location ID\",\"outputColumnRole\":\"Attribute\",\"afterColumn\":\"Location ID\"},\"applied\":true,\"inplace\":true,\"rename\":false,\"allowEdit\":false,\"generatesOutputColumns\":false,\"unsavedTransform\":false,\"parentId\":\"3\"},{\"id\":\"5\",\"type\":\"PROPERTY_CHANGE\",\"sourceColumns\":[\"Dept No\"],\"expressionSourceColumns\":[\"Dept No\"],\"outputColumns\":[],\"options\":{\"outputColumnAggrRule\":\"none\",\"outputColumnDisplayName\":\"Dept No\",\"outputColumnRole\":\"Attribute\",\"afterColumn\":\"Dept No\"},\"applied\":true,\"inplace\":true,\"rename\":false,\"allowEdit\":false,\"generatesOutputColumns\":false,\"unsavedTransform\":false,\"parentId\":\"4\"},{\"id\":\"6\",\"type\":\"PROPERTY_CHANGE\",\"sourceColumns\":[\"Class No\"],\"expressionSourceColumns\":[\"Class No\"],\"outputColumns\":[],\"options\":{\"outputColumnAggrRule\":\"none\",\"outputColumnDisplayName\":\"Class No\",\"outputColumnRole\":\"Attribute\",\"afterColumn\":\"Class No\"},\"applied\":true,\"inplace\":true,\"rename\":false,\"allowEdit\":false,\"generatesOutputColumns\":false,\"unsavedTransform\":false,\"parentId\":\"5\"},{\"id\":\"7\",\"type\":\"PROPERTY_CHANGE\",\"sourceColumns\":[\"Subclass No\"],\"expressionSourceColumns\":[\"Subclass No\"],\"outputColumns\":[],\"options\":{\"outputColumnAggrRule\":\"none\",\"outputColumnDisplayName\":\"Subclass No\",\"outputColumnRole\":\"Attribute\",\"afterColumn\":\"Subclass No\"},\"applied\":true,\"inplace\":true,\"rename\":false,\"allowEdit\":false,\"generatesOutputColumns\":false,\"unsavedTransform\":false,\"parentId\":\"6\"}],\"recommendations\":[],\"dataSubsetInfos\":{\"queryEditMode\":1,\"filterbarSettings\":{},\"uiSqlStatement\":\"

-- ── Query 4 ────────────────────────────────────────────────────────────
SELECT\\n    REPORT_DATE  AS \\\"Report Date\\\",\\n    RECORD_CATEGORY AS \\\"Record Category\\\",\\n    CASE RECORD_CATEGORY\\n        WHEN 'UNMATCHED'\\n        THEN 'UNMATCHED RECEIPT: Receipt exists in RMS; invoice not yet matched in ReIM'\\n        WHEN 'CLOSED_WRITEOFF'\\n        THEN 'WRITE-OFF SENT TO FINANCIALS: invclshp.pc closed this shipment; interfaced to AP'\\n        ELSE 'REVIEW'\\n    END                                                   AS \\\"Record Category DESC\\\",\\n    DAYS_UNMATCHED AS \\\"Days Unmatched\\\",\\n    CASE\\n        WHEN RECORD_CATEGORY = 'CLOSED_WRITEOFF' AND RECEIPT_COST_RAW &gt; 0\\n        THEN '1 - CRITICAL: Write-off with positive cost value sent to financials'\\n        WHEN RECORD_CATEGORY = 'UNMATCHED' AND DAYS_UNMATCHED &gt; 30\\n        THEN '2 - HIGH: Unmatched over 30 days - invprg.pc may purge invoice before ReIM matches'\\n        WHEN RECORD_CATEGORY = 'UNMATCHED' AND DAYS_UNMATCHED &gt; 15\\n        THEN '3 - MEDIUM: Unmatched 15-30 days - chase ReIM matching team'\\n        WHEN RECORD_CATEGORY = 'CLOSED_WRITEOFF' AND RECEIPT_COST_RAW = 0\\n        THEN '4 - REVIEW: Zero-value write-off closed by invclshp.pc'\\n        ELSE '5 - MONITOR: Under 15 days unmatched'\\n    END                                                   AS \\\"Urgency Level\\\",\\n     CASE\\n        WHEN DAYS_UNMATCHED &gt; 30 THEN 'OVERDUE - Over 30 Days'\\n        WHEN DAYS_UNMATCHED &gt; 15 THEN 'REVIEW - 15 to 30 Days'\\n        WHEN DAYS_UNMATCHED &gt; 7  THEN 'MONITOR - 7 to 15 Days'\\n        ELSE 'RECENT - Under 7 Days'\\n    END                                                   AS \\\"Aging Band\\\",\\n    SHIPMENT_NO                                           AS \\\"Shipment No\\\",\\n    MATCH_STATUS                                          AS \\\"Match Status\\\",\\n    CASE MATCH_STATUS\\n        WHEN 'U' THEN 'Unmatched'\\n        WHEN 'M' THEN 'Matched'\\n        WHEN 'C' THEN 'Closed - Write-off by invclshp.pc'\\n        ELSE NVL(MATCH_STATUS, 'NOT SET')\\n    END                                                   AS \\\"Match Status DESC\\\",\\n    ASN_NUMBER                                            AS \\\"ASN Number\\\",\\n    RECEIPT_DATE                                          AS \\\"Receipt Date\\\",\\n    PO_NUMBER                                             AS \\\"PO Number\\\",\\n    PO_STATUS                                             AS \\\"PO Status\\\",\\n    CASE PO_STATUS\\n        WHEN 'A' THEN 'Approved' WHEN 'C' THEN 'Closed'\\n        WHEN 'W' THEN 'Worksheet' WHEN 'S' THEN 'Submitted'\\n        ELSE PO_STATUS\\n    END                                                   AS \\\"PO Status DESC\\\",\\n    SUPPLIER_ID                                           AS \\\"Supplier ID\\\",\\n    SUPPLIER_NAME                                         AS \\\"Supplier Name\\\",\\n    SUPPLIER_STATUS                                       AS \\\"Supplier Status\\\",\\n    ORIGIN_COUNTRY_ID                                     AS \\\"Origin Country ID\\\",\\n    VPN,\\n    LOCATION_ID                                           AS \\\"Location ID\\\",\\n    LOC_TYPE                                              AS \\\"LOC Type\\\",\\n    CASE LOC_TYPE\\n        WHEN 'S' THEN STORE_NAME\\n        WHEN 'W' THEN WH_NAME\\n        ELSE TO_CHAR(LOCATION_ID)\\n    END                                                   AS \\\"Location Name\\\",\\n    DEPT_NO                                               AS \\\"Dept No\\\",\\n    DEPT_NAME                                             AS \\\"Dept Name\\\",\\n    CLASS_NO                                              AS \\\"Class No\\\",\\n    CLASS_NAME                                            AS \\\"Class Name\\\",\\n    SUBCLASS_NO                                           AS \\\"Subclass No\\\",\\n    SUBCLASS_NAME                                         AS \\\"Subclass Name\\\",\\n    ITEM_ID                                               AS \\\"Item ID\\\",\\n    ITEM_DESCRIPTION                                      AS \\\"Item Description\\\",\\n    UOM,\\n    QTY_ORDERED                                           AS \\\"QTY Ordered\\\",\\n    QTY_RECEIVED                                          AS \\\"QTY Received\\\",\\n    UNIT_COST                                             AS \\\"Unit Cost\\\",\\n    ROUND(RECEIPT_COST_RAW, 2)                            AS \\\"Receipt Cost\\\",\\n    INVC_XREF_ID                                          AS \\\"Invc Xref ID\\\",\\n    LINKED_INVOICE_ID                                     AS \\\"Linked Invoice ID\\\",\\n    INVOICE_TYPE                                          AS \\\"Invoice Type\\\",\\n    CASE INVOICE_TYPE\\n        WHEN 'RTV'  THEN 'Return To Vendor Invoice'\\n        WHEN 'CONS' THEN 'Consignment Invoice'\\n        WHEN 'CS'   THEN 'Credit Note'\\n        WHEN 'CN'   THEN 'Credit Note Request'\\n        WHEN 'DM'   THEN 'Debit Memo'\\n        WHEN 'OI'   THEN 'Ordinary Invoice'\\n        ELSE NVL(INVOICE_TYPE, 'NO INVOICE CREATED')\\n    END                                                   AS \\\"Invoice Type DESC\\\",\\n    INVOICE_DATE                                          AS \\\"Invoice Date\\\",\\n    INVOICE_AMOUNT                                        AS \\\"Invoice Amount\\\",\\n    INVOICE_CURRENCY                                      AS \\\"Invoice Currency\\\",\\n    PAYMENT_TERMS                                         AS \\\"Payment Terms\\\",\\n    PAYMENT_DUE_DATE                                      AS \\\"Payment Due Date\\\",\\n    VENDOR_DOC_NO                                         AS \\\"Vendor Doc No\\\",\\n    INVOICE_MATCH_STATUS                                  AS \\\"Invoice Match Status\\\",\\n    CASE INVOICE_MATCH_STATUS\\n        WHEN 'U' THEN 'Unmatched in ReIM'\\n        WHEN 'M' THEN 'Matched in ReIM'\\n        WHEN 'A' THEN 'Auto-matched'\\n        WHEN 'E' THEN 'Error in ReIM'\\n        ELSE NVL(INVOICE_MATCH_STATUS, 'NO INVOICE IN RMS')\\n    END                                                   AS \\\"Invoice Match Status DESC\\\",\\n    EXTRACTED_TO_REIM                                     AS \\\"Extracted To Reim\\\",\\n    CASE EXTRACTED_TO_REIM\\n        WHEN 'Y' THEN 'YES - Extracted by edidlinv.pc to ReIM file'\\n        WHEN 'N' THEN 'NO - Not yet extracted to ReIM'\\n        ELSE 'NO INVOICE - invclshp.pc write-off, no invoice created'\\n    END                                                   AS \\\"Reim Extraction Status\\\",\\n    CASE\\n        WHEN RECORD_CATEGORY = 'CLOSED_WRITEOFF' AND RECEIPT_COST_RAW &gt; 0\\n        THEN 'WRITE-OFF SENT TO FINANCIALS: AP should have received debit from invclshp.pc closure'\\n        WHEN RECORD_CATEGORY = 'CLOSED_WRITEOFF' AND RECEIPT_COST_RAW = 0\\n        THEN 'ZERO-VALUE WRITE-OFF: Closed with no financial impact'\\n        WHEN LINKED_INVOICE_ID IS NOT NULL AND EXTRACTED_TO_REIM = 'Y'\\n        THEN 'INVOICE EXTRACTED TO REIM: Awaiting matching in ReIM system'\\n        WHEN LINKED_INVOICE_ID IS NOT NULL AND NVL(EXTRACTED_TO_REIM,'N') = 'N'\\n        THEN 'INVOICE NOT EXTRACTED: edidlinv.pc has not yet extracted to ReIM file'\\n        WHEN LINKED_INVOICE_ID IS NULL\\n        THEN 'NO INVOICE IN RMS: Receipt received but no invoice created - check supplier'\\n        ELSE 'REVIEW'\\n    END                                                   AS \\\"Financial Status\\\",\\n    CASE\\n        WHEN RECORD_CATEGORY = 'CLOSED_WRITEOFF'\\n        THEN 'CLOSED BY invclshp.pc: Shipment exceeded Close Open Ship Days with no open invoice'\\n        WHEN LINKED_INVOICE_ID IS NULL\\n        THEN 'NO INVOICE CREATED: Supplier has not submitted invoice; check payment terms'\\n        WHEN EXTRACTED_TO_REIM = 'N'\\n        THEN 'EDIDLINV NOT RUN: Invoice exists but edidlinv.pc has not extracted it to ReIM'\\n        WHEN DAYS_UNMATCHED &gt; 30\\n        THEN 'REIM MATCHING DELAYED: Invoice extracted but ReIM has not matched it'\\n        ELSE 'NORMAL: Recent receipt awaiting ReIM invoice matching cycle'\\n    END                                                   AS \\\"Root Cause\\\",\\n    CASE\\n        WHEN RECORD_CATEGORY = 'CLOSED_WRITEOFF' AND RECEIPT_COST_RAW &gt; 0\\n        THEN 'Confirm AP has received write-off posting; verify GL account via fifgldn1/fifgldn2'\\n        WHEN LINKED_INVOICE_ID IS NULL AND DAYS_UNMATCHED &gt; 15\\n        THEN 'Invoice missing: contact supplier to submit invoice; raise manual invoice in ReIM if needed'\\n        WHEN EXTRACTED_TO_REIM = 'N'\\n        THEN 'Run edidlinv.pc or check extraction schedule; invoice must reach ReIM before payment terms expire'\\n        WHEN DAYS_UNMATCHED &gt; 30\\n        THEN 'Chase ReIM matching team; check IM_MATCH_QUEUE in ReIM for blocking exceptions'\\n        WHEN DAYS_UNMATCHED &gt; 15\\n        THEN 'Follow up with ReIM team; ensure invoice is in IM_DOC_HEAD and not in error status'\\n        ELSE 'Monitor - within normal ReIM matching window'\\n    END                                                   AS \\\"Recommended Action\\\",\\n    COMMENTS\\nFROM (\\n

-- ── Query 5 ────────────────────────────────────────────────────────────
SELECT\\n        TRUNC(SYSDATE)                                    AS REPORT_DATE,\\n        CASE\\n            WHEN sh.INVC_MATCH_STATUS = 'C' THEN 'CLOSED_WRITEOFF'\\n            ELSE 'UNMATCHED'\\n        END                                               AS RECORD_CATEGORY,\\n        TRUNC(SYSDATE) - TRUNC(sh.RECEIVE_DATE)           AS DAYS_UNMATCHED,\\n        sh.SHIPMENT                                       AS SHIPMENT_NO,\\n        sh.INVC_MATCH_STATUS                              AS MATCH_STATUS,\\n        sh.ASN                                            AS ASN_NUMBER,\\n        sh.RECEIVE_DATE                                   AS RECEIPT_DATE,\\n        sh.ORDER_NO                                       AS PO_NUMBER,\\n        oh.STATUS                                         AS PO_STATUS,\\n        oh.SUPPLIER                                       AS SUPPLIER_ID,\\n        sp.SUP_NAME                                       AS SUPPLIER_NAME,\\n        sp.SUP_STATUS                                     AS SUPPLIER_STATUS,\\n        os.ORIGIN_COUNTRY_ID                              AS ORIGIN_COUNTRY_ID,\\n        os.REF_ITEM                                       AS VPN,\\n        sh.TO_LOC                                         AS LOCATION_ID,\\n        sh.TO_LOC_TYPE                                    AS LOC_TYPE,\\n        st.STORE_NAME                                     AS STORE_NAME,\\n        wh.WH_NAME                                        AS WH_NAME,\\n        im.DEPT                                           AS DEPT_NO,\\n        d.DEPT_NAME                                       AS DEPT_NAME,\\n        im.CLASS                                          AS CLASS_NO,\\n        c.CLASS_NAME                                      AS CLASS_NAME,\\n        im.SUBCLASS                                       AS SUBCLASS_NO,\\n        sc.SUB_NAME                                       AS SUBCLASS_NAME,\\n        ss.ITEM                                           AS ITEM_ID,\\n        im.ITEM_DESC                                      AS ITEM_DESCRIPTION,\\n        im.STANDARD_UOM                                   AS UOM,\\n        NVL(ol.QTY_ORDERED,  0)                           AS QTY_ORDERED,\\n        NVL(ss.QTY_RECEIVED, 0)                           AS QTY_RECEIVED,\\n        NVL(ss.UNIT_COST,    0)                           AS UNIT_COST,\\n        NVL(ss.QTY_RECEIVED, 0) * NVL(ss.UNIT_COST, 0)   AS RECEIPT_COST_RAW,\\n        ix.ID                                             AS INVC_XREF_ID,\\n        ih.INVC_ID                                        AS LINKED_INVOICE_ID,\\n        ih.INVC_TYPE                                      AS INVOICE_TYPE,\\n        ih.INVC_DATE                                      AS INVOICE_DATE,\\n        ih.TOTAL_MERCH_COST                               AS INVOICE_AMOUNT,\\n        ih.CURRENCY_CODE                                  AS INVOICE_CURRENCY,\\n        ih.TERMS                                          AS PAYMENT_TERMS,\\n        ih.DUE_DATE                                       AS PAYMENT_DUE_DATE,\\n        ih.EXT_REF_NO                                     AS VENDOR_DOC_NO,\\n        ih.STATUS                                         AS INVOICE_MATCH_STATUS,\\n        ih.EDI_SENT_IND                                   AS EXTRACTED_TO_REIM,\\n        oh.COMMENT_DESC                                   AS COMMENTS\\n    FROM  MFCS_RDS.RDS_WV_SHIPMENT             sh\\n    JOIN  MFCS_RDS.RDS_WV_SHIPSKU              ss   ON  sh.SHIPMENT   = ss.SHIPMENT\\n    JOIN  MFCS_RDS.RDS_WV_ORDHEAD              oh   ON  sh.ORDER_NO   = oh.ORDER_NO\\n    LEFT JOIN MFCS_RDS.RDS_WV_ORDSKU           os   ON  oh.ORDER_NO   = os.ORDER_NO\\n                                                    AND  ss.ITEM      = os.ITEM\\n    LEFT JOIN MFCS_RDS.RDS_WV_ORDLOC           ol   ON  oh.ORDER_NO   = ol.ORDER_NO\\n                                                    AND  ss.ITEM      = ol.ITEM\\n                                                    AND  sh.TO_LOC    = ol.LOCATION\\n    JOIN (\\n

-- ── Query 6 ────────────────────────────────────────────────────────────
SELECT ITEM, ITEM_DESC, DEPT, CLASS, SUBCLASS, STANDARD_UOM\\n        FROM   MFCS_RDS.RDS_WV_ITEM_MASTER\\n        WHERE  TRAN_LEVEL = ITEM_LEVEL\\n    )                                          im   ON  ss.ITEM       = im.ITEM\\n    JOIN  MFCS_RDS.RDS_WV_DEPS                 d    ON  im.DEPT       = d.DEPT\\n    JOIN  MFCS_RDS.RDS_WV_CLASS                c    ON  im.DEPT       = c.DEPT\\n                                                    AND  im.CLASS     = c.CLASS\\n    JOIN  MFCS_RDS.RDS_WV_SUBCLASS             sc   ON  im.DEPT       = sc.DEPT\\n                                                    AND  im.CLASS     = sc.CLASS\\n                                                    AND  im.SUBCLASS  = sc.SUBCLASS\\n    LEFT JOIN MFCS_RDS.RDS_WV_SUPS             sp   ON  oh.SUPPLIER   = sp.SUPPLIER\\n    LEFT JOIN MFCS_RDS.RDS_WV_STORE            st   ON  sh.TO_LOC     = st.STORE\\n    LEFT JOIN MFCS_RDS.RDS_WV_WH               wh   ON  sh.TO_LOC     = wh.WH\\n    LEFT JOIN MFCS_RDS.RDS_WV_INVC_XREF        ix   ON  sh.SHIPMENT   = ix.SHIPMENT\\n    LEFT JOIN MFCS_RDS.RDS_WV_INVC_HEAD        ih   ON  ix.INVC_ID    = ih.INVC_ID\\n    WHERE\\n        sh.INVC_MATCH_STATUS NOT IN ('M')\\n        AND sh.RECEIVE_DATE &gt;= ADD_MONTHS(SYSDATE, -3)\\n)\"},\"editorCurrentState\":false,\"joins\":{\"tables\":[]}}</ds:uiOptions><ds:version>v5</ds:version></ds:datasetImportOptions>","business-model":"\"\"","active":true,"custom-attrs":"{\"src_parquet_verified\":\"true\"}","description":"External dataset","display-name":"Manual Query","locale":"sys","is-user-striped":false,"file-length":0,"type":"sql","properties-last-modified":"2026-08-04T04:42:25.867+0000","connection-namespace":"disadmin_disadmin_APPID","private-connection":false,"credential-exists":true,"connection-name":"Remote RDS MFCS Connection","provider-type":"db","provider-name":"oracle","sso-enabled":false,"datamodelname":"'ReCommon'.'RPT_304_Unmatched_Receipts_Financials'","parent-namespace":"ReCommon","parent-name":"RPT_304_Unmatched_Receipts_Financials","data-access-mode":"auto","is-data-cacheable":true,"checkpoint-metadata-stale":false,"owner-guid":"ReCommon","is-temporary":false},"datasetType":"EMBEDDED","datamodelTwoPartName":"'ReCommon'.'RPT_304_Unmatched_Receipts_Financials'"}
